types.declaration:
type levelAOptions struct {
	cases, root, config, providers, setup, out, harness string
	names                                               []string
	repeat                                              int
}

type ArchCase struct {
	ID     string `yaml:"id"`
	Status string `yaml:"status"`
	Repo   string `yaml:"repo"`
	Base   string `yaml:"base"`
	// Members makes it a workspace case: the system findings between them
	// (the evidence names a member as "<name>: path").
	Members []ArchMember `yaml:"members,omitempty"`
	Expect  []ArchExpect `yaml:"expect,omitempty"`
	Reject  []ArchExpect `yaml:"reject,omitempty"`
	Notes   string       `yaml:"notes,omitempty"`
}

type ArchMember struct {
	Name string `yaml:"name"`
	Repo string `yaml:"repo"`
	Base string `yaml:"base"`
}

type ArchResult struct {
	Case     ArchCase
	Findings []arch.Smell
	// Found and Missing are the expectations met and not; Wrong the
	// rejected findings present.
	Found, Missing, Wrong []ArchExpect
	// Property problems on any finding (M15): no evidence, no source, no
	// basis, a heuristic without confidence.
	Problems []string
	Err      error
}

type Case struct {
	ID       string   `yaml:"id"`
	Status   string   `yaml:"status"`
	Kind     string   `yaml:"kind"` // bugfix (default) or question
	Language string   `yaml:"language"`
	Repo     string   `yaml:"repo"`
	Base     string   `yaml:"base"`
	Fix      string   `yaml:"fix"`
	Problem  string   `yaml:"problem"`
	Question string   `yaml:"question"`
	Expected Expected `yaml:"expected"`
	Check    string   `yaml:"check"`
	Notes    string   `yaml:"notes"`
	// Cause is the confirmed root cause in the author's words; used only
	// to judge agent fixes, never shown to the system under test.
	Cause string `yaml:"cause"`
	// Queries overrides the searches Level A issues (default: derived
	// from the prompt, see DefaultQueries).
	Queries []Query `yaml:"queries"`

	// Path is the file the case was loaded from.
	Path string `yaml:"-"`
}

type Complementarity struct {
	Unique      map[string][]string `json:"unique"` // provider -> files only it found
	UnionRecall float64             `json:"union_recall_at_10"`
	BestSingle  float64             `json:"best_single_recall_at_10"`
	BestBy      string              `json:"best_by"`
}

type Derived struct {
	Files     []string `yaml:"files"`
	TestFiles []string `yaml:"test_files,omitempty"` // changed tests: usually not expected answers
	// Added files do not exist at base, so no provider can find them;
	// they describe the fix rather than where to look.
	AddedFiles []string `yaml:"added_files,omitempty"`
	Symbols    []string `yaml:"symbols"`
}

type Expected struct {
	Files    []string `yaml:"files"`
	Symbols  []string `yaml:"symbols"`
	Primary  string   `yaml:"primary"`
	Concepts []string `yaml:"concepts"`
	// Related lists places a good answer may point at but need not (e.g.
	// changes made for naming only): they count as correct hits and never
	// as misses.
	Related Related `yaml:"related"`
}

type ProviderSetup struct {
	Index   *Step `toml:"index"`   // before the first query
	Reindex *Step `toml:"reindex"` // after one file changed ({file})
	// Languages limits the provider to cases in these languages (empty:
	// all), e.g. graphify-csharp only understands C#.
	Languages []string `toml:"languages"`
	// NativeHint names the provider's own entry tools for native Level B
	// arms, as the harness arm's guidance names search_project.
	NativeHint string `toml:"native_hint"`
	// Exclusive providers share state across working copies (trace-mcp's
	// registry), so only one run may use them at a time.
	Exclusive bool `toml:"exclusive"`
}

type Query struct {
	Kind string `yaml:"kind" json:"kind"` // symbol, text, file or all
	Text string `yaml:"text" json:"text"`
}

type Related struct {
	Files   []string `yaml:"files"`
	Symbols []string `yaml:"symbols"`
}

type Report struct {
	StartedAt time.Time    `json:"started_at"`
	Providers []string     `json:"providers"`
	Cases     []CaseReport `json:"cases"`
}

type Setup struct {
	Providers map[string]ProviderSetup `toml:"providers"`
}

type Step struct {
	Command []string       `toml:"command"`
	MCPTool string         `toml:"mcp_tool"`
	Args    map[string]any `toml:"args"`
}

type Usage struct {
	Input         int64 `json:"input_tokens"`
	CacheCreation int64 `json:"cache_creation_input_tokens"`
	CacheRead     int64 `json:"cache_read_input_tokens"`
	Output        int64 `json:"output_tokens"`
}

type Verdict struct {
	Verdict string  `json:"verdict"` // fixed, partial or not_fixed
	Reason  string  `json:"reason"`
	CostUSD float64 `json:"cost_usd"`
}

type ranked struct {
	key           string
	best, qi, pos int
}

type searchOutput struct {
	Results []Hit    `json:"results"`
	Errors  []string `json:"errors"`
	Calls   []struct {
		LatencyMS int64 `json:"latency_ms"`
		Bytes     int   `json:"bytes"`
	} `json:"calls"`
}

type streamEvent struct {
	Type    string `json:"type"`
	Subtype string `json:"subtype"`
	Model   string `json:"model"`
	Message struct {
		Model   string `json:"model"`
		ID      string `json:"id"`
		Usage   Usage  `json:"usage"`
		Content []struct {
			Type  string          `json:"type"`
			Name  string          `json:"name"`
			Input json.RawMessage `json:"input"`
		} `json:"content"`
	} `json:"message"`
	TotalCostUSD float64 `json:"total_cost_usd"`
	NumTurns     int     `json:"num_turns"`
	Result       string  `json:"result"`
	IsError      bool    `json:"is_error"`
	Usage        *Usage  `json:"usage"`
}

type pageView struct {
	Brand    template.CSS
	Logo     template.HTML
	Machines []Machine
}

type call struct {
	tool string
	args map[string]any
}

type Options struct {
	// Command is the graphify-csharp executable.
	Command string
	// WatchArgs are extra arguments for "watch" (e.g. --input X.slnx when
	// the root holds several solutions).
	WatchArgs []string
	// Root is the project root (graphify's --root).
	Root string
	// ReadyWait bounds how long a query waits for a loading session
	// (default 3s); after that it fails at once with the session's stage, so
	// a cold start never holds up get_context. Warm starts loading early.
	ReadyWait time.Duration
	// SessionDir holds graphify's session descriptors (<id>.json); default
	// <user config dir>/Graphify.CSharp/sessions.
	SessionDir string
	// StopOnExit stops the session the adapter started when it closes
	// (the old behavior); by default it stays warm for the next one.
	StopOnExit bool
	// Idle is how long a session harness started may go unqueried before
	// an adapter's start stops it (default graphify.DefaultIdle).
	Idle time.Duration
	// StartedBy says who starts a session, for harness ui.
	StartedBy string
}

type Provider struct {
	opts Options

	mu      sync.Mutex
	session string    // warm session in use
	watch   *exec.Cmd // session started by this adapter, if any
	exited  chan struct{}
}

type edge struct {
	Relation string   `json:"relation"`
	Location location `json:"location"`
	Origin   symbol   `json:"origin"`
}

type location struct {
	File string `json:"file"`
	Line int    `json:"line"`
}

type queryResponse struct {
	Success bool `json:"success"`
	Error   *struct {
		Code    string `json:"code"`
		Message string `json:"message"`
	} `json:"error"`
	Items []json.RawMessage `json:"items"`
	Page  struct {
		HasMore bool `json:"has_more"`
	} `json:"page"`
	Scope struct {
		DiscoveryComplete *bool `json:"input_discovery_complete"`
	} `json:"scope"`
	Diagnostics []struct {
		Message string `json:"message"`
	} `json:"diagnostics"`
}

type symbol struct {
	ID       string   `json:"id"`
	Label    string   `json:"label"`
	Kind     string   `json:"declaration_kind"`
	Location location `json:"location"`
}

type Build struct {
	File, Version, OS, Arch string
	Size                    int64
	SHA256                  string
}

type Release struct {
	Dir     string
	Version string
	Builds  []Build
	Extra   []string // SHA256SUMS, RELEASE_NOTES.md when present
}

type buildView struct {
	Build
	Label, Arch, Size string
	Mine              bool
}

type platformView struct {
	Name, Note string
	Builds     []buildView
	Mine       bool
}

type Section struct {
	Doc   string `json:"doc"`   // guide, reference
	Slug  string `json:"slug"`  // as GitHub anchors it: "connecting-claude-code-and-codex"
	Title string `json:"title"` // the heading, markdown removed
	Body  string `json:"body,omitempty"`
}

type Build struct {
	Language string `json:"language"` // dotnet, typescript, go
	// Noun names a unit in this language ("project", "package", "folder").
	Noun string `json:"noun"`
	// Groups are the .NET solutions (none in other languages).
	Groups []Group `json:"solutions"`
	Units  []Unit  `json:"projects"`
	// Roles order what names say, lowest first: a unit may reference
	// roles at or below its own (heuristic).
	Roles []Role `json:"-"`
	// Words splits a unit's name into the words its role is read from,
	// last word first counted.
	Words func(Unit) []string `json:"-"`
	// Extra are smells only a language reader can see (e.g. reaching into
	// another feature's internals).
	Extra []Smell `json:"-"`
}

type Group struct {
	Path     string   `json:"path"`
	Projects []string `json:"projects"` // by Path
	Missing  []string `json:"missing,omitempty"`
}

type Layered struct {
	Unit
	// Layer: 0 for units that reference no other unit of the repository,
	// else one more than the highest layer they reference.
	Layer int `json:"layer"`
	// Role is what the name says the unit is (heuristic), "test" for tests,
	// "" when the name says nothing.
	Role string `json:"role,omitempty"`
	// ReferencedBy lists the units that reference this one, by Path.
	ReferencedBy []string `json:"referenced_by"`
}

type PackageRef struct {
	Name    string `json:"name"`
	Version string `json:"version,omitempty"`
	// Frameworks it applies to in a multi-targeting project; empty when
	// to all (TASK-0045).
	Frameworks []string `json:"frameworks,omitempty"`
	// Conditional: behind a condition the reader could not evaluate.
	Conditional bool `json:"conditional,omitempty"`
	// Unresolved: Version names a property defined nowhere the reader
	// reads ($(Name)); it is not a version.
	Unresolved bool `json:"unresolved,omitempty"`
}

type Role struct {
	Name  string
	Words []string
}

type Rule struct {
	Kind  string     // layers, forbid, only
	Sides [][]string // layers: the layers top first; forbid/only: from, to (names or patterns)
	Ref   RuleRef
}

type RuleError struct {
	Ref RuleRef
	Err string
}

type RuleGroup struct {
	Name     string
	Patterns []string
	Ref      RuleRef
}

type RuleRef struct {
	Memory string `json:"memory"`          // memory id
	Scope  string `json:"scope,omitempty"` // where it applies: project, path:..., workspace:<name>
	Type   string `json:"type,omitempty"`  // constraint, decision, convention
	Line   string `json:"line"`            // the rule as written
}

type RuleSet struct {
	Groups []RuleGroup
	Rules  []Rule
	Errors []RuleError
}

type Smell struct {
	Kind  string `json:"kind"`  // layering, test-reference, unused, no-solution, solutions-differ, missing-project, cycle, deep-import
	Level string `json:"level"` // problem, warn, info
	Title string `json:"title"`
	Why   string `json:"why"`
	// Fix is what could help: a suggestion to weigh, not a task.
	Fix     string `json:"fix,omitempty"`
	Project string `json:"project,omitempty"` // Path of the unit it is about
	// Evidence: file:line places that show it.
	Evidence []string `json:"evidence,omitempty"`
	// Key identifies the finding from one sync to the next (TASK-0030): its
	// kind and the units it is about, never line numbers or counts.
	Key string `json:"key"`
	// Measure is how big it is (contracts of a chatty link, members of a
	// circle, places that show it); a mark is reviewed when it grows.
	Measure int `json:"measure"`
	// The evidence model (HAR-0102): who found it (Source), whether it is a
	// fact of the files or a heuristic (Basis), and for a heuristic how sure
	// (Confidence, 0..1). An agent's own reading is not a finding: it comes
	// as a proposal marked as a model's interpretation (TASK-0032).
	Source     Source  `json:"source"`
	Basis      string  `json:"basis"`
	Confidence float64 `json:"confidence,omitempty"`
	// Rule is the recorded rule a boundary finding breaks (HAR-0104).
	Rule *RuleRef `json:"rule,omitempty"`
	// Rank is how much acting on it is worth among findings of its kind
	// and level, higher first (TASK-0039: a copy's size, copies and
	// packages); 0 when its producer does not rank.
	Rank float64 `json:"rank,omitempty"`
}

type Source struct {
	Provider string `json:"provider"`
	Tool     string `json:"tool,omitempty"`
}

type Unit struct {
	// Name is how the unit is called (a project's name, a package's name,
	// a folder's path below the source root).
	Name string `json:"name"`
	// Path identifies the unit: slash-separated, relative to the root
	// (a project file, a package.json, a folder).
	Path string `json:"path"`
	// Package is what the unit publishes for others to depend on ("" when
	// nothing).
	Package string `json:"package,omitempty"`
	// Version is the version it publishes its package at, when declared.
	Version string `json:"version,omitempty"`
	// Kind: "entry" (an application, host or executable), "test" or
	// "library".
	Kind       string   `json:"kind"`
	References []string `json:"references"` // other units, by Path
	// RefAt is where each reference is stated: unit Path -> "file:line".
	RefAt    map[string]string `json:"ref_at,omitempty"`
	Packages []PackageRef      `json:"packages"`
	// Solutions lists the groups (.NET solutions) that include the unit.
	Solutions []string `json:"solutions"`
}

type command struct {
	name    string
	aliases []string // accepted, not listed
	summary string
	about   string // longer description shown in the command's help
	// args names the positional arguments in usage ("<id>", "[file]");
	// minArgs..maxArgs is how many are accepted (maxArgs < 0: any).
	args             string
	minArgs, maxArgs int
	// A group has subcommands; a leaf has flags, which declares its flags
	// on fs and returns its action.
	subs []command
	// defaultSub is the subcommand a bare group runs (otherwise it lists
	// its commands).
	defaultSub string
	flags      func(fs *flag.FlagSet) action
	// raw leaves parse nothing: the action gets the arguments as given
	// (help only).
	raw action
}

type proposalInput struct {
	status, content, note string
	supersede             []string
	keepBoth, json        bool
}

type wizItem struct {
