	servers     map[string]mcpServer
}

type Branch struct {
	Path  string   `json:"path"`
	Line  int      `json:"line"`
	Words []string `json:"words"` // every choice's words, lower case
	// Choices are the words of each choice (a case, a comparison).
	Choices [][]string `json:"choices"`
}

type Contract struct {
	// Variants are the variant words (lower case), sorted.
	Variants []string `json:"variants"`
	// Operations are the templates, each the functions of one operation
	// by variant word.
	Operations []Operation `json:"operations"`
	// Branches are the places that choose among the variants by name.
	Branches []Branch `json:"branches,omitempty"`
}

type Copy struct {
	Funcs []Func `json:"funcs"` // by path and line
	// Similarity is how alike the bodies are with their names kept: 1 for
	// identical, otherwise the lowest of the pairs that joined the group.
	Similarity float64 `json:"similarity"`
}

type Func struct {
	Path string `json:"path"`
	Name string `json:"name"` // Type.Method for Go methods
	Line int    `json:"line"`
	End  int    `json:"end"`  // the body's last line
	Lang string `json:"lang"` // go, cs, ts
	// canon: locals renamed, numbers normalized, the rest kept; shape:
	// every name and literal normalized.
	canon []string
	shape []string
	// sig: its declaration's types, the result's then one per parameter
	// ("|" between): two bodies alike on other types are a template.
	sig []string
	// Override: it overrides a member of its base (C#, TS).
	Override bool `json:"override,omitempty"`
	// Wraps: the one standard-library function a Go body calls (beside
	// builtins), e.g. strings.Cut; such a helper is best inlined.
	Wraps string `json:"wraps,omitempty"`
	// units: the body's statements, for repeated sequences
	units []unit
	// Data: the body holds a decision of its own (a number other than 0
	// or 1, a string, a constant or variable of its package): copies of
	// it must agree, however small (a commit id's length, a time format).
	Data bool `json:"data,omitempty"`
}

type Operation struct {
	// Stem is the operation's name with the variant as *: Detect*.
	Stem    string            `json:"stem"`
	Funcs   []Func            `json:"funcs"`
	Variant map[string]string `json:"variant"` // Func.ID -> variant word
}

type Options struct {
	// MinIdentical and MinNear leave out bodies shorter than this
	// (canonical tokens): a getter or a one-line delegation is an idiom,
	// not a copy. Identical small helpers count (firstLine is 17 tokens).
	MinIdentical int
	MinNear      int
	// Near is the lowest similarity of a near copy (0..1): the share of
	// tokens the two bodies have in common, in order.
	Near float64
	// Shape is the lowest similarity of the shapes (names and literals
	// dropped) of functions following one template.
	Shape float64
	// Repeated is how many functions make a repeated template; two make
	// one when their bodies are at least LongPair tokens (worth a shared
	// helper even twice).
	Repeated int
	LongPair int
}

type Place struct {
	Func    Func     `json:"func"`
	Line    int      `json:"line"`
	Differs []string `json:"differs,omitempty"`
}

type Repeat struct {
	Funcs []Func `json:"funcs"` // by path and line
	// Differs: the names each function uses that not all of them do, by
	// Func.ID (a few, sorted).
	Differs map[string][]string `json:"differs"`
	// Similarity is how alike their shapes are: the lowest pair.
	Similarity float64 `json:"similarity"`
	// Tokens is the shortest body's size: a long template is worth a
	// shared base or a generic helper, a short one is a pattern.
	Tokens int `json:"tokens"`
}

type Sequence struct {
	Places     []Place  `json:"places"`
	Statements int      `json:"statements"` // doing work: not braces, idioms or bare block headers
	Tokens     int      `json:"tokens"`
	Text       []string `json:"text"` // the statements as the first place has them
	Data       bool     `json:"data"` // holds a string or number the places must agree on
	// Holder: a function whose body is the run, which the others could call.
	Holder *Func `json:"holder,omitempty"`
	key    string
}

type ctok struct {
	kind byte // i ident, n number, s string, p punctuation
	text string
	line int
}

type goFile struct {
	path string
	src  []byte
	fset *token.FileSet
	file *ast.File
}

type groups struct {
	parent []int
	low    map[int]float64 // by root, for joined sets
}

type splitter struct {
	out []unit
	cur unit
	key []string
	// goLang: Go (a func literal opens a block); literal: for each open
	// brace, whether it opens a value ({ a: 1 }, T{A: 1}), not a block
	goLang  bool
	literal []bool
}

type unit struct {
	key   string   // canonical tokens, the function's own names as "\x01"
	own   []string // the function's own names in it, in order
	raw   []string // the source tokens
	line  int
	size  int  // canonical tokens
	idiom bool // an error check, a bare return, a defer Close, a brace
	// header: it opens a block (if, for, a closure): a run needs
	// statements doing work, not only the blocks around them
	header bool
	// work: it does something: a statement, or a header calling a
	// function (if errors.Is(…) {, for sc.Scan() {)
	work bool
	// callee: the function it calls first ("EntityGuards.ThrowIfEmptyId")
	callee string
	data   bool // a string or a number other than 0 and 1
}

type CapabilityMapping struct {
	// Tool is the downstream tool name.
	Tool string `toml:"tool"`
	// Args is the argument template. String values may contain the
	// placeholders {query}, {query_name} (last part of a dotted symbol
	// name), {query_regex} (query escaped as a regular expression), {limit},
	// {limit_more} (limit + 1, a number like {limit}: asking for one more tells a server that cannot
	// say so whether more exist), {path}, {abs_path} (path joined to the
	// root), {root}, {project} (see
	// ResolveMapping), {target} (flow destination), {budget} (context size;
	// sent as a number when exact), and for package
	// capabilities {package}, {version} and {type}; a value that is
	// exactly "{limit}" is sent as a number. Arguments whose placeholders
	// have no value (e.g. no path given) are omitted.
	Args map[string]any `toml:"args"`
	// Items is the dotted path to the result array in the tool's JSON
	// response ("" = the response itself). A "*" segment walks every
	// element of a list or every entry of an object (in key order), so
	// "matches.*.lines" flattens per-file line lists; a field path "$key"
	// is then the object key above the item. Ignored for project.overview.
	Items string `toml:"items"`
	// Fields maps harness item fields to dotted paths within each result
	// item. Known fields: name, qualified_name, label, path, start_line,
	// end_line, snippet, score.
	Fields map[string]string `toml:"fields"`
	// Evidence declares how certain the answers are: "exact" (literal or
	// compiler-resolved) or "inferred" (heuristic); default by capability.
	Evidence string `toml:"evidence"`
	// Kind overrides the item kind (symbol, match, file, package, relation); the default
	// follows the capability.
	Kind string `toml:"kind"`
	// Where keeps only items whose fields (dotted paths) equal these values,
	// e.g. { is_match = true }.
	Where map[string]any `toml:"where"`
	// Error is a dotted path to an error message some servers put in an
	// otherwise successful JSON response; a non-empty value fails the call.
	Error string `toml:"error"`
	// Truncated says more results exist than were returned: a dotted path
	// to a boolean for JSON responses, a regular expression matched
	// against the text for pattern mappings.
	Truncated string `toml:"truncated"`
	// Pattern extracts items from a text (non-JSON) response instead of
	// Items/Fields: a regular expression whose named groups are item
	// fields, e.g. <f p="(?P<path>[^"]+)" score="(?P<score>\d+)". Every
	// match becomes one item.
	Pattern string `toml:"pattern"`
	// Miss is a regular expression; a response (or tool error) matching it
	// counts as no answer (e.g. "not found"), so the chain moves on. For
	// code.* capabilities a miss of every call is an empty answer; for
	// lookups (package.*) it is an error.
	Miss string `toml:"miss"`
	// Chain lists further calls for the same capability, each a mapping
	// of its own (without chain/combine). Combine "first" (default) stops
	// at the first call that answers; "all" merges every call's answers.
	Chain   []CapabilityMapping `toml:"chain"`
	Combine string              `toml:"combine"`
}

type Config struct {
	Storage   Storage                   `toml:"storage"`
	Log       Log                       `toml:"log"`
	Providers map[string]ProviderConfig `toml:"providers"`
	Sync      Sync                      `toml:"sync"`
}

type Error struct {
	Path string
	Line int // 0 when not applicable
	Err  error
}

type Log struct {
	Level string `toml:"level"`
}

type ProviderConfig struct {
	// Type selects the adapter: "" (built-in, by name) or "mcp".
	Type string `toml:"type"`
	// Pack starts from a provider pack shipped with harness (see Packs);
	// keys set in the table override the pack's.
	Pack string `toml:"pack"`
